const TRANSPOSITION_SIGNATURE=['転座の符',24,7,'照準付近の敵1体を選び、0.45秒後に180%で攻撃。通常敵とは攻撃直前の位置を交換し、その敵の攻撃を中断する。自分の移動指示・構え中の行動も解除する。無敵時間は付かない。村・ボス・訓練標的・狭い足場・他の敵と重なる移動先では、位置を変えず攻撃のみ。対象が320を超える・壁に隠れる・倒れると解除。再発動で前の符を置き換える。属性抽選で交換の仕組みは変わらない。','M8 17H42L34 9M42 17L34 25M44 39H10L18 31M10 39L18 47M15 12V22M37 34V44'];
SIGNATURE_SKILLS.push(TRANSPOSITION_SIGNATURE);Object.assign(GEM.crafted_5_1,{name:TRANSPOSITION_SIGNATURE[0],cost:24,cool:7,desc:TRANSPOSITION_SIGNATURE[3],ability:null,signature:97,tags:['spell']});
SIGNATURE_AUDIO.push(['transposition',640,.35]);SKILL_AUDIO_FAMILIES.airy.add('transposition');
function transpositionValid(s){let e=s.target;return !!(s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&e&&e.hp>0&&enemies.includes(e)&&dist(p,e)<=320&&lineClear(p,e));}
function transpositionSpace(s){let e=s.target;if(villageOpen||e.boss||e.dummy||!SPECIES[e.species]||!passable(e.x,e.y,13)||!passable(p.x,p.y,enemyHitRadius(e))||!lineClear(p,e,13))return false;return enemies.every(other=>other===e||other.hp<=0||(dist(other,e)>13+enemyHitRadius(other)&&dist(other,p)>enemyHitRadius(e)+enemyHitRadius(other)));}
const transpositionCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=transpositionCastBase(build,...args);if(GEM[build.type]?.signature!==97)return result;let s=signatureSpells.at(-1);if(s?.mode!==97)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==97||v===s);s.owner=p;s.world=dungeon;s.finished=false;if(!transpositionValid(s)){signatureSpells=signatureSpells.filter(v=>v!==s);say('320以内で見える敵を狙ってください');}return result;};
const transpositionStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==97)return transpositionStepBase(s,dt);if(!transpositionValid(s))return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<.45)return true;let e=s.target,exchange=transpositionSpace(s);s.finished=true;
 if(exchange){let from={x:p.x,y:p.y};p.x=e.x;p.y=e.y;e.x=from.x;e.y=from.y;route=[];moveGoal=null;attackTarget=null;lootTarget=null;playerAction=null;playerMoving=false;e.path=[];e.nav=0;e.attack=null;e.state='idle';e.elapsed=0;e.struck=true;e.t=Math.max(e.t||0,.65);burst(p.x,p.y,35,'#b5e7ee');}
 spellHit(e,s.damage*1.8,s.build);burst(e.x,e.y,45,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(97,true,e.x,e.y);return false;};
const transpositionPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{transpositionPaintBase();for(let s of signatureSpells){if(s.mode!==97||!transpositionValid(s))continue;let e=s.target,color=ELEMENTS[s.build.elements[0]].color;if(visibleAt(p.x,p.y))groundRing(p.x,p.y,28,color,2);if(visibleAt(e.x,e.y)){groundRing(e.x,e.y,32,color,2);if(visibleAt(p.x,p.y))paintLinkLine(p,e,'#c2a8ef',2);}}};
const transpositionStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===97?{label:'転座',value:Math.min(1,s.time/.45),waiting:true}:transpositionStatusBase(s);
